package coreapi

import (
	"context"
	"errors"
	"fmt"
	"os"
	"strings"

	"github.com/ogen-go/ogen/ogenerrors"

	"github.com/entireio/cli/cmd/entire/cli/auth"
)

// apiBasePath is appended to the control-plane origin to reach the v1
// surface. The generated spec's single server entry is "/api/v1", so the
// origin we dial is <core-host> and the client base is <core-host>/api/v1.
const apiBasePath = "/api/v1"

// New returns a *Client wired to talk to the Entire control plane (Core
// API) as the currently logged-in user.
//
// The host and bearer come from auth.ResolveControlPlaneTarget. Control-plane
// commands target a login server directly — unlike `git clone` or the data
// API, there's no resource host to match a context against — so the active
// contexts.json login is used as-is, and `entire auth use <ctx>` retargets the
// control plane onto that login server; with no active context this errors
// with the `entire login` hint. The Core API is served at <host>/api/v1. The
// bearer is resolved lazily per request, re-minting silently from the stored
// refresh token.
func New() (*Client, error) {
	// ENTIRE_TOKEN bypass: CI / workload-identity runners inject a short-
	// lived login or sa-session JWT and want control-plane commands to use
	// it verbatim, with no contexts.json (the runner never ran `entire
	// login`) and no keyring (the runner has none). Mirrors the env-token
	// path in cmd/git-remote-entire/main.go:resolveCreds — presence of the
	// var (LookupEnv, including blank) commits the CLI to this mode.
	//
	// Fail-closed: a blank or malformed value is fatal rather than a silent
	// fallback to contexts.json, which would mask a misconfigured runner.
	// The token's own aud claim becomes the control-plane origin we dial —
	// CoreURLFromEnvToken validates aud is a https bare-origin URL, and
	// makes that the resource the static bearer is sent to.
	if raw, ok := os.LookupEnv(auth.EnvTokenVar); ok {
		envToken := strings.TrimSpace(raw)
		if envToken == "" {
			return nil, fmt.Errorf("%s is set but blank", auth.EnvTokenVar)
		}
		coreURL, err := auth.CoreURLFromEnvToken(envToken)
		if err != nil {
			return nil, err //nolint:wrapcheck // CoreURLFromEnvToken already prefixes with EnvTokenVar
		}
		return NewWithBearer(coreURL, envToken)
	}

	target, err := auth.ResolveControlPlaneTarget()
	if err != nil {
		return nil, fmt.Errorf("resolve control-plane target: %w", err)
	}
	src := &providerSource{provide: target.TokenSource}
	client, err := NewClient(strings.TrimRight(target.CoreURL, "/")+apiBasePath, src)
	if err != nil {
		return nil, fmt.Errorf("build Entire API client: %w", err)
	}
	return client, nil
}

// NewWithBearer returns a *Client targeting an explicit core origin with a
// fixed bearer token — no per-request resolution or STS exchange. Used when a
// command must hit a specific login server with a token already in hand:
// e.g. `entire auth status` querying /me on the active context's core with
// that context's session token.
func NewWithBearer(coreBaseURL, token string) (*Client, error) {
	base := strings.TrimRight(coreBaseURL, "/")
	client, err := NewClient(base+apiBasePath, staticBearer{token: token})
	if err != nil {
		return nil, fmt.Errorf("build Entire API client: %w", err)
	}
	return client, nil
}

// staticBearer is a SecuritySource that returns a fixed bearer token. Same
// sessionAuth-skipping rationale as providerSource.
type staticBearer struct{ token string }

func (s staticBearer) BearerAuth(context.Context, OperationName) (BearerAuth, error) {
	return BearerAuth{Token: s.token}, nil
}

func (s staticBearer) SessionAuth(context.Context, OperationName) (SessionAuth, error) {
	return SessionAuth{}, ogenerrors.ErrSkipClientSecurity
}

// providerSource implements the generated SecuritySource, supplying the
// logged-in user's bearer token for every request from a token-provider
// func (auth.ControlPlaneTarget.TokenSource). The control plane only uses
// bearerAuth from the CLI; the sessionAuth (browser cookie) scheme is
// reported as ErrSkipClientSecurity so ogen's middleware satisfies the
// "bearerAuth OR sessionAuth" requirement via the bearer alone — without
// adding a stray `Cookie: entire_session=` header. (Returning an empty
// SessionAuth would not skip the cookie: the generated securitySessionAuth
// unconditionally calls req.AddCookie.)
type providerSource struct {
	provide func(context.Context) (string, error)
}

func (p *providerSource) BearerAuth(ctx context.Context, _ OperationName) (BearerAuth, error) {
	token, err := p.provide(ctx)
	if err != nil {
		// The per-context provider returns a tailored message that already
		// names the context, its login server, and the exact re-login command
		// — surface it verbatim rather than burying it under a generic prefix;
		// other failures (STS rejection, network) are likewise
		// self-descriptive. A bare ErrNotLoggedIn (no tailored text) gets the
		// standard login hint as a backstop.
		if errors.Is(err, auth.ErrNotLoggedIn) {
			return BearerAuth{}, fmt.Errorf("not logged in — run 'entire login': %w", err)
		}
		return BearerAuth{}, err
	}
	return BearerAuth{Token: token}, nil
}

func (p *providerSource) SessionAuth(context.Context, OperationName) (SessionAuth, error) {
	// The CLI authenticates with a bearer token, never the browser
	// session cookie. ErrSkipClientSecurity tells ogen to drop this
	// scheme entirely for the request (no Cookie header added); the
	// bearerAuth path alone satisfies the OR-requirement.
	return SessionAuth{}, ogenerrors.ErrSkipClientSecurity
}

// APIError reports the title/detail/status of a control-plane RFC 7807
// problem response, or "" if err isn't a control-plane API error. Use it
// to render a clean message instead of ogen's wrapped decode string:
//
//	if _, err := client.CreateOrg(ctx, body); err != nil {
//	    if msg := coreapi.APIError(err); msg != "" {
//	        return cli.NewSilentError(errors.New(msg))
//	    }
//	    return err
//	}
func APIError(err error) string {
	var statusErr *ErrorModelStatusCode
	if !errors.As(err, &statusErr) {
		return ""
	}
	m := statusErr.Response
	switch {
	case m.Detail.Set && m.Detail.Value != "":
		return m.Detail.Value
	case m.Title.Set && m.Title.Value != "":
		return m.Title.Value
	default:
		return fmt.Sprintf("control-plane request failed with status %d", statusErr.StatusCode)
	}
}

package auth

import (
	"fmt"
	"net/url"
	"strings"

	"github.com/entireio/auth-go/tokens"
)

// EnvTokenVar is the environment variable that, when set, bypasses
// contexts.json and the keyring entirely: its value is used verbatim as the
// login JWT for repo-scoped token exchange. This is the CI / workload-identity
// path — a runner injects a short-lived login or sa-session JWT and clones
// without an interactive `entire login`.
const EnvTokenVar = "ENTIRE_TOKEN"

// CoreURLFromEnvToken derives the home-region core URL from an ENTIRE_TOKEN
// JWT's audience claim. Login and sa-session JWTs carry aud=<home-region URL>,
// which is what STS routing keys on — so we read aud, not iss (iss may be a
// regional core that can't mint the cross-region exchange).
//
// SECURITY: the returned URL becomes the host the env token is POSTed to as a
// subject_token during exchange. ParseClaims does NOT verify the signature, so
// the audience is attacker-controlled if a forged token is injected. This
// function only enforces the *shape* of a safe endpoint (https, bare origin);
// the caller MUST additionally verify the URL is a trusted core for the target
// cluster (see clusterdiscovery.ResolveClusterCores) before exchanging, or a
// forged aud could redirect the token to an arbitrary host.
//
// Structural rules, all required:
//   - the aud is a well-formed absolute URL,
//   - scheme is https (no cleartext token exchange),
//   - it carries a host and no userinfo, path, query, or fragment — entire
//     cores are bare origins (https://core.example.com), so anything richer is
//     either a misconfigured token or an attempt to smuggle a path/redirect.
//
// The aud claim may be a single string or an array (RFC 7519 §4.1.3);
// ParseClaims normalises both to a slice. Non-URL audiences (e.g. an OAuth
// client_id like "entire-cli") are skipped; the first URL-shaped audience is
// validated strictly. A token with no URL-shaped aud is rejected with a clear
// error rather than silently falling back to context resolution.
func CoreURLFromEnvToken(rawToken string) (string, error) {
	claims, err := tokens.ParseClaims(rawToken)
	if err != nil {
		return "", fmt.Errorf("parse %s claims: %w", EnvTokenVar, err)
	}
	for _, aud := range claims.Audience {
		u, perr := url.Parse(aud)
		if perr != nil || u.Scheme == "" {
			// Opaque (non-URL) audience such as an OAuth client_id — skip it.
			continue
		}
		// URL-shaped: enforce the strict origin rules. A URL-shaped-but-invalid
		// aud is a hard error (fail closed), never silently skipped.
		return validateCoreAudience(u)
	}
	return "", fmt.Errorf("%s must be a login or sa-session JWT whose aud is the home-region URL; found no URL-shaped audience claim", EnvTokenVar)
}

// validateCoreAudience enforces that u is a safe entire-core origin and
// returns its canonical form (scheme://host, no trailing slash).
func validateCoreAudience(u *url.URL) (string, error) {
	switch {
	case u.Scheme != "https":
		return "", fmt.Errorf("%s aud %q must use https; refusing to exchange the token over %s", EnvTokenVar, u.Redacted(), u.Scheme)
	case u.Host == "":
		return "", fmt.Errorf("%s aud %q has no host", EnvTokenVar, u.Redacted())
	case u.User != nil:
		return "", fmt.Errorf("%s aud %q must not contain userinfo", EnvTokenVar, u.Redacted())
	case u.Path != "" && u.Path != "/":
		return "", fmt.Errorf("%s aud %q must be a bare origin with no path", EnvTokenVar, u.Redacted())
	case u.RawQuery != "":
		return "", fmt.Errorf("%s aud %q must not contain query parameters", EnvTokenVar, u.Redacted())
	case u.Fragment != "":
		return "", fmt.Errorf("%s aud %q must not contain a fragment", EnvTokenVar, u.Redacted())
	}
	return strings.TrimRight(u.Scheme+"://"+u.Host, "/"), nil
}

	// not Getenv, so we can tell set-empty from unset), we commit to the
	// env-token path and any failure to use it is fatal — never a silent
	// fallback to context auth, which would mask a misconfigured CI runner.
	// Read and trim once here, the only place we touch it, so every downstream
	// consumer (aud derivation and the exchanged subject_token) sees the
	// cleaned value; a trailing newline from $(cat token) is common. An empty
	// or whitespace-only value fails closed.
	if raw, ok := os.LookupEnv(auth.EnvTokenVar); ok {
		envToken := strings.TrimSpace(raw)
		if envToken == "" {
			return nil, fmt.Errorf("%s is set but blank", auth.EnvTokenVar)
		}
		return resolveEnvTokenCreds(ctx, envToken, parsedURL.Host, clusterBaseURL, userdirs.Cache(), httpClient)
	}

	// Resolve which login context authenticates this cluster: the cluster's
	// login servers are taken from the cluster_cores.json cache (or a live
	// /.well-known fetch on miss/expiry), then the account is selected from
	// local contexts — active context if eligible, else the sole eligible
	// one, else an explicit-choice error.
	cfgDir := userdirs.Config()
	clusterCtx, err := clusterdiscovery.ResolveContextForCluster(ctx, cfgDir, userdirs.Cache(), parsedURL.Host, httpClient, debuglog.Printf)
	if err != nil {
		return nil, err //nolint:wrapcheck // ResolveContextForCluster already returns a user-facing error; preserved verbatim for the "fatal: <msg>" surface
	}

	// The login-JWT provider transparently refreshes an expired login JWT
	// from the stored refresh token (serialised across processes, rotated
	// tokens persisted) before repocreds exchanges it for repo-scoped tokens.
	loginProvider, err := auth.NewRefreshingLoginProvider(clusterCtx, httpClient.Transport, skipTLS)
	if err != nil {
		return nil, err //nolint:wrapcheck // NewRefreshingLoginProvider already returns a user-facing error
	}

	// Mint repo-scoped tokens by exchanging the context's login JWT at its
	// login server's /oauth/token, cached per (repo, action) for this invocation.
	return repocreds.New(clusterCtx.CoreURL, clusterBaseURL, loginProvider, httpClient), nil
}

// resolveEnvTokenCreds builds the repo-cred cache for the ENTIRE_TOKEN path.
// Split out of resolveCreds with explicit clusterHost/cacheDir params (no
// os.Getenv / userdirs.Cache globals) so the trust gate below is unit-testable
// against a fake well-known server.
//
// SECURITY: coreURL is derived from the env token's *unverified* aud claim, and
// it becomes the host the token is POSTed to as a subject_token during
// exchange. Before trusting it, we confirm the core is one the target cluster
// actually advertises — anchored to the clone URL's host the user typed (TLS to
// its /.well-known/entire-cluster.json), not to the token's own claims. Without
// this gate a forged aud could redirect the token to an attacker-chosen host.
//
// The gate is only as strong as that TLS verification: with
// ENTIRE_TLS_SKIP_VERIFY=true (a local-dev escape hatch) the well-known fetch
// is no longer authenticated, so a MITM could advertise an attacker host as a
// trusted core. Do not combine ENTIRE_TOKEN with ENTIRE_TLS_SKIP_VERIFY in
// CI / workload-identity environments.
func resolveEnvTokenCreds(ctx context.Context, envToken, clusterHost, clusterBaseURL, cacheDir string, httpClient *http.Client) (*repocreds.Cache, error) {
	coreURL, err := auth.CoreURLFromEnvToken(envToken)
	if err != nil {
		return nil, err //nolint:wrapcheck // CoreURLFromEnvToken already returns a user-facing, ENTIRE_TOKEN-prefixed error
	}
	cores, err := clusterdiscovery.ResolveClusterCores(ctx, cacheDir, clusterHost, httpClient, debuglog.Printf)
	if err != nil {
		return nil, err //nolint:wrapcheck // ResolveClusterCores returns a user-facing discovery error
	}
	if !coreTrusted(coreURL, cores) {
		return nil, fmt.Errorf("%s aud %q is not a trusted login server for cluster %s (advertised: %s); the token belongs to a different cluster",
			auth.EnvTokenVar, coreURL, clusterHost, strings.Join(cores, ", "))
	}
	debuglog.Printf("authenticating via %s; core=%s", auth.EnvTokenVar, coreURL)
	return repocreds.New(coreURL, clusterBaseURL, func(context.Context) (string, error) {
		return envToken, nil
	}, httpClient), nil
}

// coreTrusted reports whether coreURL is in the cluster's advertised core
// set, comparing on trailing-slash-insensitive equality to match how core
// URLs are compared elsewhere (contexts.ContextsForIssuer, auth.sameIssuer).
func coreTrusted(coreURL string, trusted []string) bool {
	want := strings.TrimRight(coreURL, "/")
	for _, t := range trusted {
		if strings.TrimRight(t, "/") == want {
			return true
		}
	}
	return false
}

// gitActionFromRequest classifies a smart-HTTP request as "pull" or "push"
// so the right repo-scoped token can be minted. Returns "" when the
// endpoint isn't a recognised git smart-HTTP route.
func gitActionFromRequest(req *http.Request) string {
	path := req.URL.Path
	switch req.Method {
	case http.MethodPost:

	var preamble bytes.Buffer
	for _, spec := range refspecs {
		fmt.Fprintf(&preamble, "%04x%s\n", len(spec)+5, spec)
	}
	preamble.WriteString("0000")

	args := append([]string{"send-pack", "--stateless-rpc", "--helper-status", "--stdin"},
		opts.SendPackArgs()...)
	args = append(args, t.ErrorBaseURL())
	sp := exec.CommandContext(ctx, "git", args...)
	sp.Stderr = os.Stderr
	spIn, err := sp.StdinPipe()
	if err != nil {
		return fmt.Errorf("send-pack stdin pipe: %w", err)
	}
	spOut, err := sp.StdoutPipe()
	if err != nil {
		return fmt.Errorf("send-pack stdout pipe: %w", err)
	}
	if err := sp.Start(); err != nil {
		return fmt.Errorf("starting send-pack: %w", err)
	}

	respCh := make(chan io.ReadCloser, 1)
	feedErr := make(chan error, 1)
	go func() {
		defer spIn.Close()
		if _, err := spIn.Write(preamble.Bytes()); err != nil {
			feedErr <- fmt.Errorf("writing refspecs to send-pack: %w", err)
			return
		}
		if _, err := spIn.Write(advertisement); err != nil {
			feedErr <- fmt.Errorf("writing advertisement to send-pack: %w", err)
			return
		}
		resp, ok := <-respCh
		if !ok {
			feedErr <- nil
			return
		}
		// io.Copy may still be reading after send-pack has consumed the
		// report-status — the HTTP chunked terminator hasn't necessarily
		// arrived yet. If main closed resp during that read, the body's
		// Read would fail with "use of closed network connection" and
		// the helper would exit non-zero on a push that actually
		// succeeded. Own the close here so it runs strictly after Copy.
		defer resp.Close()
		if _, err := io.Copy(spIn, resp); err != nil {
			feedErr <- fmt.Errorf("piping receive-pack response to send-pack: %w", err)
			return
		}
		feedErr <- nil
	}()

	spOutReader := bufio.NewReader(spOut)
	var requestBody bytes.Buffer
	if err := gitproto.ReadSendPackRequest(spOutReader, &requestBody); err != nil {
		close(respCh)
		killAndWaitSendPack(sp, "after reading send-pack request failed")
		return fmt.Errorf("reading send-pack request: %w", err)
	}
	amendedBody, err := gitproto.AppendAgentToReceivePackRequest(requestBody.Bytes(), Agent)
	if err != nil {
		close(respCh)
		killAndWaitSendPack(sp, "after amending receive-pack agent failed")
		return fmt.Errorf("amending receive-pack agent: %w", err)
	}

	resp, err := t.ServiceRPC(ctx, serviceReceivePack, bytes.NewReader(amendedBody))
	if err != nil {
		close(respCh)
		killAndWaitSendPack(sp, "after posting receive-pack failed")
		return fmt.Errorf("posting receive-pack: %w", err)
	}
	respCh <- resp
	close(respCh)

	// Send-pack's stdout sequence after we write the response:
	//   <0000>                       <- packet_flush(out) at send-pack.c:759
	//   ok refs/heads/...            <- print_helper_status (plain text)
	//   error refs/...
	// Drain the trailing flush so git sees only the newline-delimited
	// status lines that transport-helper.c:push_update_refs_status
	// expects.
	//
	// resp is closed by the feeder goroutine (above), not here — closing
	// while io.Copy is mid-read aborts the body Read with "use of closed
	// network connection" and turns successful pushes into fatal errors.
	flushBuf := make([]byte, 4)
	if _, err := io.ReadFull(spOutReader, flushBuf); err != nil {
		return fmt.Errorf("reading send-pack trailing flush: %w", err)
	}
	if string(flushBuf) != "0000" {
		return fmt.Errorf("expected trailing flush from send-pack, got %q", flushBuf)
	}

	helperStatus, err := io.ReadAll(spOutReader)
	if err != nil {
		return fmt.Errorf("reading helper-status: %w", err)
	}

	// Relay helper-status before checking exit codes. send-pack exits
	// non-zero on per-ref rejections (D/F conflict, protected branch,
	// hook decline); the buffered `error refs/X <reason>` lines are
	// what git's transport-helper.c reads to print `! [remote rejected]
	// refs/X (<reason>)`. Returning early on Wait/feed errors swallowed
	// them, leaving users with only `send-pack exited with error: exit
	// status 1`.
	if _, err := stdout.Write(helperStatus); err != nil {
		return fmt.Errorf("writing helper-status: %w", err)
	}
	if _, err := fmt.Fprintln(stdout); err != nil {
		return fmt.Errorf("writing push terminator: %w", err)
	}

	// Wait for send-pack first: its exit code is the authoritative
	// signal for push success. If send-pack exited 0, it parsed a
	// valid receive-pack report-status — the protocol completed.
	// Any feeder error after that point is cleanup noise: io.Copy
	// reading from resp can race with the server-side close of the
	// underlying TCP socket (httptest.Server.Close in parallel CI
	// tests, idle-conn reaping in long-running daemons) and surface
	// "use of closed network connection" *after* send-pack has
	// already drained everything it needed. Failing the push on
	// that turned successful pushes into fatal errors.
	spErr := sp.Wait()
	feedRes := <-feedErr
	if spErr == nil {
		return nil
	}
	if feedRes != nil {
		return errors.Join(feedRes, fmt.Errorf("send-pack exited after feeder error: %w", spErr))
	}
	return fmt.Errorf("send-pack exited with error: %w", spErr)
}

