function normalizeReviewCommentLocation(
  anchors: DiffAnchors | null,
  comment: ParsedReviewComment,
): CreateCommentLocationInput {
  const explicit = comment.location
  const filePath = locationFilePath(comment)

  if (explicit?.granularity === "file") {
    return { ...explicit, granularity: "file", file_path: filePath }
  }
  if (explicit?.granularity === "whole_change") {
    return { ...explicit, granularity: "whole_change", file_path: explicit.file_path ?? filePath }
  }

  const startLine = Math.max(1, explicit?.start_line ?? comment.start_line ?? comment.line ?? 1)
  const endLine = Math.max(startLine, explicit?.end_line ?? comment.line ?? startLine)
  const selectedText =
    explicit?.selected_text ||
    selectedTextFromPatch(anchors?.byPath.get(filePath)?.rightLines, startLine, endLine)
  if (selectedText) {
    return {
      ...explicit,
      granularity: startLine === endLine ? "line" : "range",
      file_path: filePath,
      start_line: startLine,
      ...(startLine === endLine ? {} : { end_line: endLine }),
      selected_text: truncate(selectedText, MAX_SELECTED_TEXT_LENGTH),
    }
  }

  return { granularity: "file", file_path: filePath }
}

