709	// createTrailReviewFinding posts a single finding through the current API flow:
710	// start a review session, then submit a one-item comment batch under it. It
711	// returns the created (or already-existing) finding.
712	func createTrailReviewFinding(ctx context.Context, client *api.Client, trailID string, input api.TrailReviewCommentInput) (api.TrailReviewComment, error) {
713		review, err := startTrailReview(ctx, client, trailID)
714		if err != nil {
715			return api.TrailReviewComment{}, err
716		}
717		resp, err := client.Post(ctx, trailReviewBatchCommentsPath(trailID, review.ReviewID), api.TrailReviewCommentBatchRequest{
718			Comments: []api.TrailReviewCommentInput{input},
719		})
720		if err != nil {
721			return api.TrailReviewComment{}, fmt.Errorf("create finding: %w", err)
722		}
723		defer resp.Body.Close()
724		if err := checkTrailResponse(resp); err != nil {
725			return api.TrailReviewComment{}, err
726		}
727		var batch api.TrailReviewCommentBatchResponse
728		if err := api.DecodeJSON(resp, &batch); err != nil {
729			return api.TrailReviewComment{}, fmt.Errorf("decode finding batch response: %w", err)
730		}
731		if len(batch.Results) == 0 {
732			return api.TrailReviewComment{}, errors.New("create finding: server returned no results")
733		}
734		result := batch.Results[0]
735		if result.Status == trailReviewBatchResultError {
736			if result.Error != nil {
737				return api.TrailReviewComment{}, fmt.Errorf("create finding: %s: %s", result.Error.Code, result.Error.Message)
738			}
739			return api.TrailReviewComment{}, errors.New("create finding: server reported an error")
740		}
741		if result.Comment == nil {
742			return api.TrailReviewComment{}, errors.New("create finding: server did not return the finding")
743		}
744		return *result.Comment, nil
745	}
