747	// startTrailReview opens a review session for a trail. The body is left empty
748	// so the server resolves the code version (base/head) from the trail itself.
749	// The API rejects a lone head_sha — base_sha and head_sha must be supplied
750	// together or not at all — and computing a correct base SHA client-side is out
751	// of scope for a single-finding add, so neither is sent.
752	func startTrailReview(ctx context.Context, client *api.Client, trailID string) (api.TrailReviewStartResponse, error) {
753		resp, err := client.Post(ctx, trailReviewStartPath(trailID), api.TrailReviewStartRequest{})
754		if err != nil {
