+	data, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(relPath))) //nolint:gosec // path is the user-supplied --file resolved under the repo root.
+	if err != nil {
+		return "", fmt.Errorf("read %s for selected text: %w; pass --selected-text", relPath, err)
+	}
+	lines := strings.Split(string(data), "\n")
+	// A trailing newline yields a final empty element that is not a real line;
+	// drop it so line counts match the file's actual lines.
+	if n := len(lines); n > 0 && lines[n-1] == "" {
+		lines = lines[:n-1]
+	}
