+// fileHasUncommittedChanges reports whether relPath (repo-root-relative) has any
+// staged, unstaged, or untracked changes — a non-empty `git status --porcelain`
+// for the path. Untracked files report changes too, since their contents are not
+// part of any commit the trail could reference.
+func fileHasUncommittedChanges(ctx context.Context, root, relPath string) (bool, error) {
+	out, err := exec.CommandContext(ctx, "git", "-C", root, "status", "--porcelain", "--", relPath).Output()
+	if err != nil {
+		return false, fmt.Errorf("git status %s: %w", relPath, err)
+	}
+	return strings.TrimSpace(string(out)) != "", nil
+}
